import type {ConfigField} from './configurationTypes';

// Field-level evidence for developer-facing configuration. Unset values remain unknown.
const verified='2026-11-01';
type Section=ConfigField['section'];
const source=(title:string,url:string)=>({title,url,verified});
const L='https://docs.aws.amazon.com/lambda/latest/dg/';
const A='https://docs.aws.amazon.com/apigateway/latest/developerguide/';
const D='https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/';
const S='https://docs.aws.amazon.com/AmazonS3/latest/userguide/';
const Q='https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/';
const N='https://docs.aws.amazon.com/sns/latest/dg/';
const E='https://docs.aws.amazon.com/eventbridge/latest/userguide/';
const F='https://docs.aws.amazon.com/step-functions/latest/dg/';
const field=(key:string,label:string,kind:ConfigField['kind'],section:Section,help:string,extra:Partial<ConfigField>={}):ConfigField=>({key,label,kind,section,help,...extra});
const text=(key:string,label:string,section:Section,help:string,extra:Partial<ConfigField>={})=>field(key,label,'text',section,help,extra);
const select=(key:string,label:string,options:string[],section:Section,help:string,extra:Partial<ConfigField>={})=>field(key,label,'select',section,help,{options,...extra});
const bool=(key:string,label:string,section:Section,help:string,extra:Partial<ConfigField>={})=>field(key,label,'boolean',section,help,extra);
const num=(key:string,label:string,section:Section,help:string,extra:Partial<ConfigField>={})=>field(key,label,'number',section,help,extra);
const resource=(key:string,label:string,services:string[],section:Section,help:string,extra:Partial<ConfigField>={})=>field(key,label,'resource',section,help,{resourceServices:services,...extra});
const doc=(key:string,label:string,section:Section,help:string,documentType:NonNullable<ConfigField['documentType']>='json',extra:Partial<ConfigField>={})=>field(key,label,documentType==='yaml'?'yaml':'json',section,help,{documentType,...extra});
const table=(key:string,label:string,section:Section,help:string,itemFields:ConfigField[],extra:Partial<ConfigField>={})=>field(key,label,'table',section,help,{itemFields,...extra});
const kv=(key:string,label:string,section:Section,help:string,extra:Partial<ConfigField>={})=>field(key,label,'key-value',section,help,extra);
const when=(apiType:string)=>({field:'apiType',values:[apiType]});
function profile(title:string,url:string,objectives:string[],fields:ConfigField[]):ConfigField[]{
 const enrich=(f:ConfigField):ConfigField=>({...f,source:f.source??source(title,url),objectives:f.objectives??objectives,tier:f.tier??'core',...(f.itemFields?{itemFields:f.itemFields.map(enrich)}:{})});
 return fields.map(enrich);
}
